    zstep; rewrite sxb_sval; clear RDB;
    sjoinF rY J; [| sjoin_close_j rY].

  Notation FOB10 r jp := [C8 (Z_to_bv 64 (de_s2 r)); C8 (Z_to_bv 64 TB); C8 (Z_to_bv 64 (de_s1 r)); C8 (Z_to_bv 64 TB);
