  Lemma fdA_setup : forall r R m2 (jp junk : list byte)
      (y1 y5 y6 y7 y10 y11 y12 y13 y20 y21 y22 y23 y25 y26 y28 y30 y31 : word),
    tail_loop bs d dcap true (Datatypes.S (Z.to_nat dcap)) r = R -> R = decompress_usingDTable bs d dcap true ->
    RF_huf_fdw_st.res_ok R ->
    bitd_ok bs (de_bd r) -> bd_bits (de_bd r) <= 2^29 -> zlen (de_out r) <= dcap - 2 -> Forall (fun c => 0 <= c < 256) (de_out r) ->
    u8arr asegs m2 DST (map (Z_to_bv 8) (de_out r) ++ junk) -> zlen junk = dcap - zlen (de_out r) ->
    munch W0 m0 m2 -> wmono asegs m0 m2 -> mem_inv asegs m2 -> stk asegs m2 lo SP1 -> 0 < zlen bs ->
    rw_cells asegs m2 (SP1 + 48) (FOB10 r jp) ->
    evtF asegs RNG Q
      (MS (mkR y1 (Z_to_bv 64 SP1) gp tp y5 y6 y7 (Z_to_bv 64 SPV) (Z_to_bv 64 SP1) y10 y11 y12 y13 (Z_to_bv 64 (de_s2 r))
               (Z_to_bv 64 (-70)) (Z_to_bv 64 (S0 + 8)) (Z_to_bv 64 (DST + zlen (de_out r))) (Z_to_bv 64 FF)
               (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880)) y20 y21 y22 y23 (Z_to_bv 64 (DST + dcap - 2)) y25 y26
               (Z_to_bv 64 2147450880) y28 (Z_to_bv 64 (de_s1 r)) y30 y31)
          FR (Z_to_bv 64 0x97318) fc None m2 (seg_rom asegs)).
