  (* [comment removed for export] *)
  Ltac fdA_junc_tac EZ PV :=
    lazymatch goal with
    | OUT2 : u8arr asegs ?m2 DST (map (Z_to_bv 8) (de_out ?r) ++ ?junk), LJ2 : zlen ?junk = _,
      MU02 : munch W0 m0 ?m2, ST2 : stk asegs ?m2 lo SP1, EQ : decompress_usingDTable bs d dcap true = _,
      ROK : RF_huf_fdw_st.res_ok _, OKbr : bitd_ok bs (de_bd ?r), Bbr : bd_bits (de_bd ?r) <= 2^29,
      OBr : Forall _ (de_out ?r) |- _ =>
      do 7 zstep; let KJ := fresh "KJ" in zstep; if_cases KJ; zify_cond KJ;
      [ (* [comment removed for export] *)
        eapply fdA_setup; [reflexivity| symmetry; exact EQ| rewrite <- EQ; exact ROK| exact OKbr| exact Bbr| lia| exact OBr
                          | eassumption| eassumption| eassumption| eassumption| eassumption| eassumption| eassumption| ];
        replace (AF_huf_fdt.bd_regF S0 (de_bd r)) with PV by (unfold AF_huf_fdt.bd_regF; rewrite EZ; reflexivity);
        eassumption
      | (* [comment removed for export] *)
        zstep;
        replace (Z_to_bv 64 (-70)) with (Z_to_bv 64 (2^64 - 70)) by (apply Z_to_bv_eqm; reflexivity);
        lazymatch goal with H : rw_cells asegs ?mj (SP1 + 48) _ |- evtF _ _ _ (MS _ _ _ _ _ ?mj _) =>
          let j48' := fresh "j48'" in let FO' := fresh "FO'" in
          destruct (rw_cells_forget _ _ _ _ H) as (j48' & FO'); cbn [cells_size csize Nat.add] in FO' end;
        eapply fdA_exit; [eassumption| eassumption| eassumption| eassumption| eassumption| | lia];
        rewrite EQ; rewrite AF_huf_fdt.ftailA_loop_S; unfold FseNCount.Zlength;
        replace (dcap - 2 <? zlen (de_out r)) with true by (symmetry; apply Z.ltb_lt; lia);
        cbn [dresA]; unfold ZSTD_error_dstSize_tooSmall; split; [reflexivity| lia] ]
    end.

  (* [comment removed for export] *)
  Lemma fdA_main : forall m d3 (st1 st2 : Z) jp (w88 : word) (x1 x7 x10 x11 x12 x13 x17 x21 x22 x23 x28 x30 x31 : word),
    munch W0 m0 m -> wmono asegs m0 m -> mem_inv asegs m -> stk asegs m lo SP1 -> 0 < zlen bs -> u8arr asegs m DST jd ->
    rw_cells asegs m (SP1 + 48) [C8 (Z_to_bv 64 st2); C8 (Z_to_bv 64 TB); C8 (Z_to_bv 64 st1); C8 (Z_to_bv 64 TB);
                                 C8 (Z_to_bv 64 (bd_cont d3)); C4 w88; CB 4 jp; C8 (Z_to_bv 64 (S0 + bd_ptr d3));
                                 C8 (Z_to_bv 64 S0); C8 (Z_to_bv 64 (S0 + 8))] ->
    bitd_ok bs d3 -> bd_bits d3 <= 64 -> bd_zero d3 = false -> 0 <= st1 < 2^tl -> 0 <= st2 < 2^tl ->
    RF_huf_fdw_st.res_ok (decompress_usingDTable bs d dcap true) ->
    decompress_usingDTable bs d dcap true =
      (let! x := main_loop bs d dcap true (Datatypes.S (Z.to_nat dcap)) (mkDec [] st1 st2 d3) in
       tail_loop bs d dcap true (Datatypes.S (Z.to_nat dcap)) x) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 SP1) gp tp (Z_to_bv 64 64) (Z_to_bv 64 (bd_cont d3)) x7 (Z_to_bv 64 SPV)
                            (Z_to_bv 64 SP1) x10 x11 x12 x13 (Z_to_bv 64 st2) (Z_to_bv 64 (bd_bits d3)) (Z_to_bv 64 (S0 + 8)) x17
                            (Z_to_bv 64 FF) (Z_to_bv 64 (Z.shiftr FF 3 + 2147450880)) (Z_to_bv 64 AZEROFILLED) x21 x22 x23
                            (Z_to_bv 64 (DST + dcap)) (Z_to_bv 64 (DST + dcap - 3)) (Z_to_bv 64 DST) (Z_to_bv 64 2147450880)
                            x28 (Z_to_bv 64 st1) x30 x31)
